#!/usr/bin/env bash
# seq2cause-bench — xl / latent / seed 3 — the per-sequence truth rule forced-ok-counterfactual, generated 2026-11-11
# (plans/per-sequence-rules.md, addendum 2026-11-11). Per corpus: pull the engine tier (the score tier, the
# oracle tables and the engine's three inputs); per grain build the truth file of the read that holds
# trace/core/shipped/frozen (truthbuild re-runs the touched shards and refuses unless they equal the
# oracle tables), then score that cell and the three floor rows twice: under first-caller-parent into
# out/<corpus>/identity/ (must equal the landed records) and under forced-ok-counterfactual into
# out/<corpus>/results/. The reads are the landed test reads, fetched as input artifacts; no method runs
# and there is no GPU work. Sizing: the re-runs stay under 2 GB; the host is bought for the target that
# every command loads (xl: 70–80 GiB at the session grain on a 256 GiB host).
# One command per line; the runner's cwd is the harness directory; set -e stops at the first failure.
set -euo pipefail

python -m seq2causebench.pull --repo chadyuk/trace-bench --revision v0.3.0 --rung xl --variant latent --seed 3 --tier engine --dest corpora --output-folder out/xl-latent-s3/pull-engine

python -m seq2causebench.truthbuild --corpus corpora/instances/xl/latent/seed=3 --run-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --max-lag 63 --shards auto --null-forcing-ops 10 --output-folder out/xl-latent-s3/results/truth-forced-ok-counterfactual/request
python -m seq2causebench.seqscore --corpus corpora/instances/xl/latent/seed=3 --run-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --cell trace/core/shipped/frozen/request --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/xl-latent-s3/identity/trace/core/shipped/frozen/request/seqscore
python -m seq2causebench.floorseq --corpus corpora/instances/xl/latent/seed=3 --read-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/xl-latent-s3/identity/trace/core/shipped/frozen/request/seqscore/seqscore.json --floor-read results/xl/latent/seed=3/test-read/floors-request --floor-cell floor/topology/none/frozen/request --row broadcast --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/xl-latent-s3/identity/floor/topology/none/frozen/request/seqscore-broadcast-on-trace-core
python -m seq2causebench.floorseq --corpus corpora/instances/xl/latent/seed=3 --read-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/xl-latent-s3/identity/trace/core/shipped/frozen/request/seqscore/seqscore.json --floor-read results/xl/latent/seed=3/test-read/floors-request --floor-cell floor/bigram/none/frozen/request --row broadcast --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/xl-latent-s3/identity/floor/bigram/none/frozen/request/seqscore-broadcast-on-trace-core
