python -m seq2causebench.seqscore --corpus corpora/instances/xl/latent/seed=3 --run-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --cell trace/core/shipped/frozen/request --max-lag 63 --rule forced-ok-counterfactual --truth-file out/xl-latent-s3/results/truth-forced-ok-counterfactual/request/seqtruth-forced-ok-counterfactual-request.json --output-folder out/xl-latent-s3/results/trace/core/shipped/frozen/request/seqscore-forced-ok-counterfactual
python -m seq2causebench.floorseq --corpus corpora/instances/xl/latent/seed=3 --read-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/xl-latent-s3/results/trace/core/shipped/frozen/request/seqscore-forced-ok-counterfactual/seqscore.json --floor-read results/xl/latent/seed=3/test-read/floors-request --floor-cell floor/topology/none/frozen/request --row broadcast --max-lag 63 --rule forced-ok-counterfactual --truth-file out/xl-latent-s3/results/truth-forced-ok-counterfactual/request/seqtruth-forced-ok-counterfactual-request.json --output-folder out/xl-latent-s3/results/floor/topology/none/frozen/request/seqscore-broadcast-on-trace-core-forced-ok-counterfactual
