python -m seq2causebench.floorseq --corpus corpora/instances/xl/latent/seed=3 --read-dir input/xl-latent-s3/test-read/discover-request-core-all-c1-N8 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/xl-latent-s3/results/trace/core/shipped/frozen/request/seqscore-forced-ok-counterfactual/seqscore.json --floor-read results/xl/latent/seed=3/test-read/floors-request --floor-cell floor/bigram/none/frozen/request --row adjacent --max-lag 63 --rule forced-ok-counterfactual --truth-file out/xl-latent-s3/results/truth-forced-ok-counterfactual/request/seqtruth-forced-ok-counterfactual-request.json --output-folder out/xl-latent-s3/results/floor/bigram/none/frozen/request/seqscore-adjacent-on-trace-core-forced-ok-counterfactual

python -m seq2causebench.truthbuild --corpus corpora/instances/xl/latent/seed=3 --run-dir input/xl-latent-s3/test-read/discover-session-core-all-c2-N16 --max-lag 63 --shards auto --null-forcing-ops 10 --output-folder out/xl-latent-s3/results/truth-forced-ok-counterfactual/session
